<template>
  <div class="page-heading"><div><h1 class="page-title">今日需回访</h1><p>业务时间按 Asia/Shanghai 计算，仅展示当前数据范围内未完结、未无效表单。</p></div><el-button @click="load">刷新</el-button></div>
  <div class="summary-grid"><article><span>今日待回访</span><strong>{{ data.counts.today }}</strong></article><article class="danger"><span>已逾期未回访</span><strong>{{ data.counts.overdue }}</strong></article><article class="success"><span>今日已完成回访</span><strong>{{ data.counts.completed }}</strong></article></div>
  <section class="content-panel"><el-tabs v-model="tab"><el-tab-pane :label="`今日待回访 ${data.counts.today}`" name="today"/><el-tab-pane :label="`逾期未回访 ${data.counts.overdue}`" name="overdue"/></el-tabs><el-table :data="tab==='today'?data.today:data.overdue" v-loading="loading" row-key="id"><el-table-column prop="name" label="姓名" min-width="110"/><el-table-column prop="phone" label="电话" width="130"/><el-table-column prop="project.name" label="项目" min-width="120"/><el-table-column prop="channelSource" label="渠道" min-width="110"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag>{{row.status.name}}</el-tag></template></el-table-column><el-table-column label="负责人" width="120"><template #default="{row}">{{row.owner.nickname||row.owner.username}}</template></el-table-column><el-table-column label="下次回访时间" width="180"><template #default="{row}"><strong :class="{overdue:row.overdue}">{{fmt(row.nextFollowUpAt)}}</strong></template></el-table-column><el-table-column label="最近跟进" width="180"><template #default="{row}">{{fmt(row.lastFollowUpAt)}}</template></el-table-column></el-table></section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { getConsultationCallbacks, type ConsultationFormItem } from '../api/admin';
const loading=ref(false);const tab=ref('today');const data=reactive<{counts:{today:number;overdue:number;completed:number};today:ConsultationFormItem[];overdue:ConsultationFormItem[]}>({counts:{today:0,overdue:0,completed:0},today:[],overdue:[]});
async function load(){loading.value=true;try{Object.assign(data,await getConsultationCallbacks())}finally{loading.value=false}}function fmt(value?:string){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'}onMounted(load);
</script>
<style scoped>.page-heading{display:flex;justify-content:space-between;gap:16px;margin-bottom:16px}.page-heading p{margin:4px 0;color:var(--admin-text-muted)}.summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:14px}.summary-grid article{padding:18px;border:1px solid var(--admin-border);border-radius:10px;background:#fff}.summary-grid span{display:block;color:var(--admin-text-muted)}.summary-grid strong{display:block;margin-top:8px;color:var(--admin-primary);font-size:30px}.summary-grid .danger strong,.overdue{color:#c45656}.summary-grid .success strong{color:#56836c}@media(max-width:700px){.summary-grid{grid-template-columns:1fr}.page-heading{flex-direction:column}}</style>
